using HakutaiKagami.Core.Contracts;
using HakutaiKagami.Core.Messaging;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class DelegationReturnRetryTests
{
    static WorldSession New(long until=long.MaxValue)=>new(DelegationMission.Create(until:until));
    static void At(WorldSession s,long at){while(s.Seconds<at){s.SetPaused(false);var before=s.Seconds;s.AdvanceTo(at);Assert.True(s.Seconds>before);}}
    static long Due(WorldSession s,string m)=>MessageFlow.Latest(s.DiagnosticSnapshot().Messaging,m).DueAt;
    static DelegationArrival Arrival(WorldSession s)=>s.DiagnosticSnapshot().Delegation!.Arrivals.Single();
    static EntityId Start(WorldSession s){var r=DelegationMission.Build(s.DiagnosticSnapshot(),"request:return-target",RegionalAction.Move);Assert.Equal(ResultCode.Accepted,s.IssueRegional(r,s.Revision).Code);At(s,Due(s,s.DiagnosticSnapshot().Region!.Commands.Single().Message));At(s,s.DiagnosticSnapshot().Delegation!.Plans.Single().Units.SelectMany(u=>u.Route).Select(l=>l.EndAt).Max());return r.Id;}
    static void FailAndKnow(WorldSession s,string message,bool loseFailure=false){var a=MessageFlow.Latest(s.DiagnosticSnapshot().Messaging,message);s.DiagnosticTransport((f,t)=>MessageFlow.Fail(f,message));At(s,a.DueAt);var failure=s.DiagnosticSnapshot().Messaging.Messages.Single(m=>m.Kind=="delivery-failure"&&m.Body==a.Id);if(loseFailure)s.DiagnosticTransport((f,t)=>MessageFlow.Fail(f,failure.Id));At(s,Due(s,failure.Id));Assert.Equal(!loseFailure,MessageFlow.FailureKnown(s.DiagnosticSnapshot().Messaging,a.Id,ContractFixture.Clerk.Value));}
    static DelegationQuestion Ask(WorldSession s,EntityId target,bool resend=true,string id="request:return-query"){var q=new DelegationQuestion(new(id),target,true,resend);Assert.Equal(ResultCode.Accepted,s.QueryDelegation(q,s.PlayerControl,s.Revision).Code);return q;}
    static void Receive(WorldSession s,DelegationQuestion q)=>At(s,Due(s,DelegationInquiry.MessageId(q.Id)));
    [Fact] public void SenderCannotRetryBeforeReceivingFailureReport(){var s=New();var target=Start(s);var report=Arrival(s).Message;s.DiagnosticTransport((f,t)=>MessageFlow.Fail(f,report));var q=Ask(s,target);Receive(s,q);Assert.Equal(1,MessageFlow.Latest(s.DiagnosticSnapshot().Messaging,report).Number);var reply=s.DiagnosticSnapshot().Messaging.Messages.Single(m=>m.Kind==DelegationInquiry.ReplyKind);var answer=ContractJson.Read<DelegationAnswer>(System.Text.Encoding.UTF8.GetBytes(reply.Body));Assert.Empty(answer.Retried!);}
    [Fact] public void KnownFailureResendsTheSameOriginalWithARealPath(){var s=New();var target=Start(s);var report=Arrival(s);var original=s.DiagnosticSnapshot().Messaging.Messages.Single(m=>m.Id==report.Message);FailAndKnow(s,report.Message);var q=Ask(s,target);Receive(s,q);var w=s.DiagnosticSnapshot();var attempt=MessageFlow.Latest(w.Messaging,report.Message);Assert.Equal(2,attempt.Number);Assert.Equal(original,w.Messaging.Messages.Single(m=>m.Id==report.Message));Assert.Equal(ContractJson.Write(report),ContractJson.Write(w.Delegation!.Arrivals.Single()));var d=w.Region!.Deliveries.Single(d=>d.Attempt==attempt.Id);Assert.Equal(s.Seconds,d.Path[0].StartAt);At(s,attempt.DueAt);Assert.True(MessageFlow.Knows(s.DiagnosticSnapshot().Messaging,report.Message,s.PlayerControl.Value));Assert.Contains(s.DiagnosticSnapshot().Messaging.Receipts,r=>r.MessageId==report.Message);Assert.True(DelegationInquiry.View(s,s.PlayerControl).Last().OriginalReceived);Assert.Single(s.DiagnosticSnapshot().Delegation!.Plans);}
    [Fact] public void LostFailureReportDoesNotEnableOriginalResend(){var s=New();var target=Start(s);var report=Arrival(s).Message;FailAndKnow(s,report,true);var q=Ask(s,target);Receive(s,q);Assert.Equal(1,MessageFlow.Latest(s.DiagnosticSnapshot().Messaging,report).Number);}
    [Fact] public void OrdinaryInquiryPreservesPreviousNoResendBehavior(){var s=New();var target=Start(s);var report=Arrival(s).Message;FailAndKnow(s,report);var q=Ask(s,target,false);Receive(s,q);Assert.Equal(1,MessageFlow.Latest(s.DiagnosticSnapshot().Messaging,report).Number);}
    [Fact] public void DuplicateQueryCannotCreateAnotherCopy(){var s=New();var target=Start(s);var report=Arrival(s).Message;FailAndKnow(s,report);var q=Ask(s,target);Receive(s,q);var bytes=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.AlreadyAccepted,s.QueryDelegation(q,s.PlayerControl,0).Code);Assert.Equal(bytes,ContractJson.Write(s.DiagnosticSnapshot()));Assert.Equal(2,MessageFlow.Latest(s.DiagnosticSnapshot().Messaging,report).Number);}
    [Fact] public void ThreeOriginalAttemptsRemainTheHardLimit(){var s=New();var target=Start(s);var report=Arrival(s).Message;for(int i=1;i<=3;i++){FailAndKnow(s,report);var q=Ask(s,target,id:"request:copy/"+i);Receive(s,q);Assert.Equal(Math.Min(3,i+1),MessageFlow.Latest(s.DiagnosticSnapshot().Messaging,report).Number);}Assert.Equal(3,s.DiagnosticSnapshot().Messaging.Attempts.Count(a=>a.MessageId==report));}
    [Fact] public void NewReturnAddressDoesNotTrackPlayersTrueLocation(){var s=New();var target=Start(s);var report=Arrival(s).Message;FailAndKnow(s,report);Assert.Equal(ResultCode.Accepted,s.HandleSupply(new("request:pack"),s.PlayerControl,true,FieldSupply.Capacity,s.Revision).Code);Assert.Equal(ResultCode.Accepted,s.SetRegionalActive(true,s.Revision).Code);var q=Ask(s,target);var w=s.DiagnosticSnapshot();var dispatch=w.Region!.Deliveries.Single(d=>w.Messaging.Attempts.Single(a=>a.Id==d.Attempt).MessageId==DelegationInquiry.MessageId(q.Id));Assert.Equal(ResultCode.Accepted,s.SetRegionalActive(false,s.Revision).Code);Receive(s,q);w=s.DiagnosticSnapshot();var retry=w.Region!.Deliveries.Single(d=>d.Attempt==MessageFlow.Latest(w.Messaging,report).Id);Assert.Equal(dispatch.Origin,retry.Address);Assert.NotEqual(RegionalBattle.Position(w,s.PlayerControl),retry.Address);}
    [Theory][InlineData(false)][InlineData(true)] public void LateOlderQuestionCannotUndoNewerKnownReturnAddress(bool sameTick){var s=New();var target=Start(s);var report=Arrival(s).Message;FailAndKnow(s,report);var old=Ask(s,target,id:"request:older");long oldDue=Due(s,DelegationInquiry.MessageId(old.Id));Assert.Equal(ResultCode.Accepted,s.HandleSupply(new("request:pack"),s.PlayerControl,true,FieldSupply.Capacity,s.Revision).Code);Assert.Equal(ResultCode.Accepted,s.SetRegionalActive(true,s.Revision).Code);if(!sameTick)At(s,s.Seconds+1);var fresh=Ask(s,target,false,"request:newer");long freshDue=Due(s,DelegationInquiry.MessageId(fresh.Id));Assert.True(freshDue<oldDue);var w=s.DiagnosticSnapshot();var source=w.Region!.Deliveries.Single(d=>w.Messaging.Attempts.Single(a=>a.Id==d.Attempt).MessageId==DelegationInquiry.MessageId(fresh.Id)).Origin;At(s,oldDue);w=s.DiagnosticSnapshot();Assert.Equal(source,w.Region!.Deliveries.Single(d=>d.Attempt==MessageFlow.Latest(w.Messaging,report).Id).Address);}
    [Fact] public void ExpiredMilitaryMandateDoesNotCancelOwnReturnLetters(){var s=New(500);var target=Start(s);var report=Arrival(s).Message;FailAndKnow(s,report);At(s,501);var grants=ContractJson.Write(s.DiagnosticSnapshot().CommandMandates);var q=Ask(s,target);Receive(s,q);Assert.Equal(2,MessageFlow.Latest(s.DiagnosticSnapshot().Messaging,report).Number);Assert.Equal(grants,ContractJson.Write(s.DiagnosticSnapshot().CommandMandates));}
    [Fact] public void LegacyQuestionBodyKeepsItsExactShape(){var bytes=System.Text.Encoding.UTF8.GetBytes("{\"Id\":\"request:old\",\"Directive\":\"request:directive\",\"Destination\":true}");var q=ContractJson.Read<DelegationQuestion>(bytes);Assert.False(q.Resend);Assert.Equal(bytes,ContractJson.Write(q));}
    [Fact] public void LegacyAnswerBodyKeepsItsExactShape(){var bytes=System.Text.Encoding.UTF8.GetBytes("{\"Query\":\"request:old\",\"Directive\":\"request:directive\",\"At\":\"5\",\"Receipt\":\"applied\",\"Progress\":\"moving\",\"Arrival\":null}");var a=ContractJson.Read<DelegationAnswer>(bytes);Assert.Null(a.Retried);Assert.Equal(bytes,ContractJson.Write(a));}
    [Fact] public void InvalidDefaultIdsAreRejectedWithoutThrowing(){var s=New();Assert.Equal(ResultCode.NotAvailable,s.QueryDelegation(new(default,default,true,true),s.PlayerControl,s.Revision).Code);}
    [Theory][InlineData(0)][InlineData(1)][InlineData(20)][InlineData(50)][InlineData(200)]
    public void SaveRestorePreservesRequestAndPhysicalOriginalRetry(int delta){var s=New();var target=Start(s);var report=Arrival(s).Message;FailAndKnow(s,report);Ask(s,target);At(s,s.Seconds+delta);s.SetPaused(true);var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"delegation-return-"+Guid.NewGuid().ToString("N")),s.DiagnosticSnapshot().Definitions);store.Save(s,"case",s.DiagnosticSnapshot().WorldId,new(0,1));var host=new WorldSessionHost(New());Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("case"),host.Current,host.Current.Revision));At(s,s.Seconds+350);At(host.Current,s.Seconds);Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot()),ContractJson.Write(host.Current.DiagnosticSnapshot()));Assert.Equal(DelegationInquiry.View(s,s.PlayerControl),DelegationInquiry.View(host.Current,host.Current.PlayerControl));}
    [Theory][InlineData("summary")][InlineData("address")][InlineData("knowledge")]
    public void ForgedRetryCannotLoad(string kind){var s=New();var target=Start(s);var report=Arrival(s).Message;FailAndKnow(s,report);var q=Ask(s,target);Receive(s,q);var w=s.DiagnosticSnapshot();var m=w.Messaging.Messages.Last(m=>m.Kind==DelegationInquiry.ReplyKind);if(kind=="summary"){var a=ContractJson.Read<DelegationAnswer>(System.Text.Encoding.UTF8.GetBytes(m.Body));w.Messaging.Messages=w.Messaging.Messages.Select(x=>x.Id==m.Id?x with{Body=System.Text.Encoding.UTF8.GetString(ContractJson.Write(a with{Retried=[]}))}:x).ToArray();}if(kind=="address"){var id=MessageFlow.Latest(w.Messaging,report).Id;w.Region=w.Region! with{Deliveries=w.Region.Deliveries.Select(d=>d.Attempt==id?d with{Address=new(0,0)}:d).ToArray()};}if(kind=="knowledge")w.Messaging.Knowledge=w.Messaging.Knowledge.Where(k=>k.CharacterId!=ContractFixture.Clerk.Value||!w.Messaging.Messages.Any(m=>m.Id==k.MessageId&&m.Kind=="delivery-failure")).ToArray();Assert.Throws<InvalidDataException>(()=>ContractValidation.Validate(w));}
}
